1	// The constructor keeps public named params (`remoteDataSource`,
2	// `accessTokenProvider`) distinct from the private fields they initialize,
3	// matching `auth_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:async';
6	
7	import 'package:fpdart/fpdart.dart';
8	
9	import '../../../../core/failure/failure.dart';
10	import '../../../../core/network/access_token_provider.dart';
11	import '../../../../core/session/session_expiry_notifier.dart';
12	import '../../domain/entities/session_status.dart';
13	import '../../domain/repositories/session_repository.dart';
14	import '../datasources/auth_remote_data_source.dart';
15	
16	/// Owns the one broadcast [SessionStatus] stream the epic's AD requires.
17	/// [restoreSession] is unconditional — no client-side expiry math — and
18	/// covers the I/O matrix (spec-1-4):
19	/// - no stored refresh token -> no network call, emits `unauthenticated`
20	///   immediately.
21	/// - stored token, backend accepts -> new pair persisted via `saveSession`,
22	///   emits `authenticated`.
23	/// - stored token, backend reports `AUTH_EXPIRED`/`AUTH_INVALID` (dead
24	///   token) -> `clearSession`, emits `unauthenticated`.
25	/// - stored token, any other failure (offline/timeout/...) -> fail-closed:
26	///   emits `unauthenticated` WITHOUT clearing storage, so the next boot
27	///   retries naturally.
28	class SessionRepositoryImpl implements SessionRepository {
29	  SessionRepositoryImpl({
30	    required AuthRemoteDataSource remoteDataSource,
31	    required AccessTokenProvider accessTokenProvider,
32	    required SessionExpiryNotifier sessionExpiryNotifier,
33	  }) : _remoteDataSource = remoteDataSource,
34	       _accessTokenProvider = accessTokenProvider,
35	       _sessionExpiryNotifier = sessionExpiryNotifier {
36	    // Story 1.5 — the one bridge from `core`'s expiry signal onto this
37	    // feature's own `SessionStatus` stream (Design Notes). Subscribed for
38	    // this repository's whole lifetime; cancelled in [dispose].
39	    _expirySubscription = _sessionExpiryNotifier.expiredEvents.listen(
40	      (_) => _onSessionExpired(),
41	      // Mirrors `statusStream`'s own internal subscription a few lines
42	      // below: no current `SessionExpiryNotifier` implementation ever
43	      // errors, but without this, a future one that did would surface as
44	      // an unhandled zone exception instead of just being dropped here.
45	      onError: (_, _) {},
46	    );
47	  }
48	
49	  final AuthRemoteDataSource _remoteDataSource;
50	  final AccessTokenProvider _accessTokenProvider;
51	  final SessionExpiryNotifier _sessionExpiryNotifier;
52	  late final StreamSubscription<void> _expirySubscription;
53	  final StreamController<SessionStatus> _statusController =
54	      StreamController<SessionStatus>.broadcast();
55	
56	  /// The last status emitted, so a consumer that subscribes *after* the
57	  /// first emission (a later `StreamBuilder`, or Story 1.5/1.6's own
58	  /// listener) still sees current state immediately rather than nothing
59	  /// until the next change — see [statusStream].
60	  SessionStatus? _lastStatus;
61	
62	  @override
63	  Stream<SessionStatus> get statusStream {
64	    // `Stream.multi` runs this callback once per listener (and, with
65	    // `isBroadcast: true`, supports more than one simultaneously) — each
66	    // new listener synchronously gets the cached last status (if any)
67	    // before being attached to the live broadcast controller for whatever
68	    // comes next. This is this story's whole reason to not just expose
69	    // `_statusController.stream` directly: a plain broadcast stream only
70	    // ever delivers *future* events to a listener that joins late.
71	    return Stream<SessionStatus>.multi((controller) {
72	      final last = _lastStatus;
73	      if (last != null) {
74	        controller.add(last);
75	      }
76	      final subscription = _statusController.stream.listen(
77	        controller.add,
78	        onError: controller.addError,
79	        onDone: controller.close,
80	      );
81	      controller.onCancel = subscription.cancel;
82	    }, isBroadcast: true);
83	  }
84	
85	  void _emit(SessionStatus status) {
86	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
87	    // an in-flight `restoreSession()` call — without this, a late `.add()`
88	    // after `.close()` would throw an unhandled `StateError` instead of
89	    // just being a no-op on an already-torn-down repository.
90	    if (_statusController.isClosed) {
91	      return;
92	    }
93	    _lastStatus = status;
94	    _statusController.add(status);
95	  }
96	
97	  /// "Always" boundary — a mid-session expiry only ever matters while the
98	  /// user is currently [SessionStatus.authenticated]; any other current
99	  /// status (not yet decided at boot, already unauthenticated/logged out,
100	  /// or already [SessionStatus.expired] from an earlier event) is a
101	  /// silent no-op — covers both the "expiry while not authenticated"
102	  /// post-logout race and the "already-open overlay" double-event case in
103	  /// the I/O matrix (a second event here never re-emits once [_lastStatus]
104	  /// is already [SessionStatus.expired]).
105	  void _onSessionExpired() {
106	    if (_lastStatus == SessionStatus.authenticated) {
107	      _emit(SessionStatus.expired);
108	    }
109	  }
110	
111	  @override
112	  Future<Either<Failure, Unit>> restoreSession() async {
113	    String? refreshToken;
114	    try {
115	      refreshToken = await _accessTokenProvider.readRefreshToken();
116	    } catch (error) {
117	      // A thrown platform exception from the native secure-storage channel
118	      // must never escape unmapped (RNF09) — fail closed, same as any other
119	      // unreadable session.
120	      _emit(SessionStatus.unauthenticated);
121	      return left(Failure.malformedResponse(message: error.toString()));
122	    }
123	
124	    if (refreshToken == null || refreshToken.isEmpty) {
125	      // Fresh install / post-logout (null), or a stored-but-empty token
126	      // (the backend response schema has no `minLength` on `refreshToken`,
127	      // so an empty string is a theoretically valid stored value) — either
128	      // way, no network call: `auth-refresh`'s own request schema requires
129	      // `minLength: 1`, so an empty token would only fail server-side.
130	      _emit(SessionStatus.unauthenticated);
131	      return left(
132	        const Failure.authExpired(message: 'No stored session to restore'),
133	      );
134	    }
135	
136	    final result = await _remoteDataSource.refresh(refreshToken);
137	    return result.match(
138	      (failure) async {
139	        // Only a backend-confirmed dead token clears storage; any other
140	        // failure (offline, timeout, malformed response, ...) leaves it
141	        // untouched so the next boot retries naturally.
142	        if (failure is AuthExpired || failure is AuthInvalid) {
143	          try {
144	            await _accessTokenProvider.clearSession();
145	          } catch (_) {
146	            // Best-effort clear — the session is already being treated as
147	            // unauthenticated below regardless of whether this succeeds.
148	          }
149	        }
150	        _emit(SessionStatus.unauthenticated);
151	        return left(failure);
152	      },
153	      (session) async {
154	        try {
155	          await _accessTokenProvider.saveSession(
156	            accessToken: session.accessToken,
157	            refreshToken: session.refreshToken,
158	          );
159	        } catch (error) {
160	          _emit(SessionStatus.unauthenticated);
161	          return left(Failure.malformedResponse(message: error.toString()));
162	        }
163	        _emit(SessionStatus.authenticated);
164	        return right(unit);
165	      },
166	    );
167	  }
168	
169	  @override
170	  Future<void> dispose() async {
171	    await _expirySubscription.cancel();
172	    await _statusController.close();
173	  }
174	}
