30	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
31	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
32	/// epic's UX constraints).
33	///
34	/// Story 1.4 scope: `home` branches on `SessionRepository.statusStream`
35	/// instead of hardcoding `AuthScreen` — `restoreSession()` fires once at
36	/// boot (unconditional, no client-side expiry math) and the stream's first
37	/// emission decides whether the user lands on `AuthScreen` or the post-auth
38	/// placeholder. No `go_router` yet (Story 1.6): the `MaterialApp`/`Navigator`
39	/// shape is unchanged, and a successful signup/login still simply
40	/// pushes-replaces via `onAuthenticated`.
41	///
42	/// Story 1.5 scope: a mid-session expiry (the same stream's `expired`
43	/// value) never changes which screen `home` renders — `build()`'s
44	/// `StreamBuilder` branch below treats it identically to `authenticated`.
45	/// The only extra reaction is scheduling the `ConfirmationDialog` overlay
46	/// on top of that same screen, from inside that same (sole) subscription —
47	/// `SessionRepository.statusStream`'s real implementation is a broadcast
48	/// `Stream.multi`, but several existing tests mock it as a plain
49	/// single-subscription `Stream.value(...)`, so a *second* independent
50	/// `.listen()` here would break those by listening to it twice.
51	class CerneApp extends StatefulWidget {
52	  const CerneApp({super.key});
53	
54	  @override
55	  State<CerneApp> createState() => _CerneAppState();
56	}
57	
58	class _CerneAppState extends State<CerneApp> {
59	  late final SessionRepository _sessionRepository;
60	
61	  // Cached once: `SessionRepository.statusStream`'s getter builds a new
62	  // `Stream.multi` instance on every access (code review of
63	  // story-1-4-silent-session-refresh-persistence), so reading it straight
64	  // into `StreamBuilder.stream` on every `build()` would make it resubscribe
65	  // and lose its current status on each rebuild instead of staying on one
66	  // subscription for this widget's lifetime.
67	  late final Stream<SessionStatus> _statusStream;
68	
69	  // Code review of story-1-5: `ConfirmationDialog.isOpen` only guards
70	  // against a *second* overlay stacking while one is already showing — it
71	  // goes back to `false` the moment the first one closes. Nothing today
72	  // transitions `SessionStatus` away from `expired` once it's reached, so
73	  // without this separate flag, any later rebuild of `CerneApp` that still
74	  // observes `expired` (e.g. a hot reload, or a future dependency this
75	  // widget picks up) would call `ConfirmationDialog.show` again and reopen
76	  // the overlay on top of whatever the user already navigated to after
77	  // confirming it once.
78	  bool _expiryOverlayShown = false;
79	
80	  @override
81	  void initState() {
82	    super.initState();
83	    _sessionRepository = sl<SessionRepository>();
84	    _statusStream = _sessionRepository.statusStream;
85	    // Fire-and-forget: the outcome reaches the UI through `statusStream`
86	    // below, not through this call's return value. `restoreSession()`
87	    // already maps every internal failure to `Left`/an `unauthenticated`
88	    // emission and never throws. This `catchError` is NOT a UI recovery
89	    // path — its handler's return value is discarded by `unawaited` and
90	    // never reaches `statusStream`, so it does not unblock `build()`'s
91	    // `_BootLoadingScreen` branch. It exists purely so a future regression
92	    // that broke the "never throws" contract above would surface as a
93	    // logged message instead of an unhandled zone exception.
94	    unawaited(
95	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
96	    );
97	  }
98	
99	  /// Story 1.5's whole reaction to an `expired` snapshot (I/O matrix —
100	  /// every other status is a no-op, since `SessionRepositoryImpl` already
101	  /// only ever emits `expired` from `authenticated`, and this is called
102	  /// from the same `StreamBuilder` subscription that renders the screen,
103	  /// not a second one).
104	  ///
105	  /// `showGeneralDialog` (inside `ConfirmationDialog.show`) pushes a route,
106	  /// which must never happen mid-`build()` — deferred to
107	  /// `addPostFrameCallback`. `_expiryOverlayShown` (not
108	  /// `ConfirmationDialog.isOpen`, which resets as soon as the overlay
109	  /// closes) makes this a one-shot per `expired` episode: nothing today
110	  /// transitions the status back out of `expired`, so without that guard a
111	  /// later rebuild would reopen an overlay the user already confirmed.
112	  void _maybeShowExpiryOverlay(BuildContext context, SessionStatus? status) {
113	    if (status != SessionStatus.expired || _expiryOverlayShown) {
114	      return;
115	    }
116	    _expiryOverlayShown = true;
117	    WidgetsBinding.instance.addPostFrameCallback((_) {
118	      if (!context.mounted) {
119	        return;
120	      }
121	      ConfirmationDialog.show(
122	        context: context,
123	        builder: (dialogContext) => ConfirmationDialog(
124	          icon: Icons.lock_outline,
125	          title: 'Sessão expirada',
126	          message:
127	              'Sua sessão expirou por segurança. Entre novamente para '
128	              'continuar — sua conversa continua aqui.',
129	          caption: 'o histórico e a posição do scroll são preservados',
130	          confirmLabel: 'Entrar novamente',
131	          barrierColor: DesignTokens.colorScrim,
132	          onConfirm: () {
133	            Navigator.of(dialogContext).pop();
134	            if (!context.mounted) {
135	              return;
136	            }
137	            Navigator.of(context).push(
138	              MaterialPageRoute(
139	                builder: (_) => const _BiometricReauthPlaceholder(),
140	              ),
141	            );
142	          },
143	        ),
144	      );
145	    });
146	  }
147	
148	  // `catchError`'s handler must still complete the Future with a value of
149	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
150	  // handler would try to complete it with `null`, which isn't assignable
151	  // to that non-nullable type and would itself throw.
152	  static Either<Failure, Unit> _asUnauthenticated(
153	    Object error,
154	    StackTrace stackTrace,
155	  ) {
156	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
157	    return left(Failure.malformedResponse(message: error.toString()));
158	  }
159	
160	  @override
161	  Widget build(BuildContext context) {
162	    return MaterialApp(
163	      debugShowCheckedModeBanner: false,
164	      home: StreamBuilder<SessionStatus>(
165	        stream: _statusStream,
166	        builder: (context, snapshot) {
167	          if (!snapshot.hasData) {
168	            // No emission yet: brief-blank for the happy path (RNF01's
169	            // 300ms threshold) — `_BootLoadingScreen` only surfaces a
170	            // spinner once the wait actually crosses that.
171	            return const _BootLoadingScreen();
172	          }
